import {chromium, webkit, expect} from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

// Uses real Fluid output generated by Tests/Functional/carousel.php --html.
const base = process.env.ASTRYX_TEST_URL ?? 'https://typo3-astryx.ddev.site';
const fixtures = fs.readFileSync(process.env.ASTRYX_CAROUSEL_HTML ?? '/tmp/astryx-carousel-fixtures.html', 'utf8');
const output = process.env.ASTRYX_TEST_OUTPUT ?? '/tmp/astryx-carousel-evidence';
fs.mkdirSync(output, {recursive: true});
const extension = path.resolve('packages/typo3_astryx');
const publicAssets = path.resolve('public/_assets');
const assetDirectory = fs.readdirSync(publicAssets).find(name => {
  try { return fs.realpathSync(path.join(publicAssets, name)) === path.join(extension, 'Resources/Public'); } catch { return false; }
});
assert(assetDirectory, 'Missing Composer public-asset link');
const manifest = JSON.parse(fs.readFileSync('public/_assets/vite/.vite/manifest.json', 'utf8'));
const entry = Object.entries(manifest).find(([key]) => /(?:typo3-astryx|typo3_astryx)\/Resources\/Private\/JavaScript\/Main\.entry\.js$/.test(key))?.[1];
assert(entry, 'Missing consuming Vite entrypoint');
// Vite extracts shared StyleX selectors into a common CSS bundle used by both entrypoints.
const viteCss = [...new Set([...entry.css, ...Object.entries(manifest).filter(([key, value]) => key.startsWith('_') && value.file.endsWith('.css')).map(([, value]) => value.file)])];
const assets = {
  packaged: {js: `_assets/${assetDirectory}/Assets/astryx.js`, css: [`_assets/${assetDirectory}/Assets/astryx.css`]},
  vite: {js: `_assets/vite/${entry.file}`, css: viteCss.map(file => `_assets/vite/${file}`)},
};
const documentHtml = (mode, direction = 'ltr') => `<!doctype html><html lang="en" dir="${direction}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><base href="${base}/"><title>Carousel pagination</title>${assets[mode].css.map(file => `<link rel="stylesheet" href="${file}">`).join('')}<style>body{margin:0;padding:24px}main{max-width:800px;margin:auto}h1{font-size:28px;margin-bottom:16px}</style><script type="module" src="${assets[mode].js}"></script></head><body class="astryx-root" data-astryx-theme="neutral" data-astryx-mode="light"><main><h1>Carousel pagination</h1>${fixtures}</main></body></html>`;
const report = [];
for (const name of (process.env.ASTRYX_TEST_BROWSERS ?? 'chromium,webkit').split(',')) {
  const browser = await ({chromium, webkit}[name]).launch({env: {...process.env, TMPDIR: '/tmp'}});
  try {
    for (const mode of Object.keys(assets)) {
      const context = await browser.newContext({ignoreHTTPSErrors: true, viewport: {width: 1100, height: 900}});
      const page = await context.newPage();
      const errors = [], failedAssets = [];
      page.on('pageerror', error => errors.push(error.message));
      page.on('response', response => { if (response.url().startsWith(base) && response.status() >= 400) failedAssets.push(response.url()); });
      for (const direction of ['ltr', 'rtl']) {
        await page.route(base + '/__astryx-carousel-test__', route => route.fulfill({contentType: 'text/html', body: documentHtml(mode, direction)}));
        await page.goto(base + '/__astryx-carousel-test__', {waitUntil: 'networkidle'});
        for (const width of [1100, 390]) {
          await page.setViewportSize({width, height: 900});
          for (const position of ['top-left', 'top-center', 'top-right', 'bottom-left', 'bottom-center', 'bottom-right', 'default', 'invalid']) {
            const root = page.locator(`[data-fixture-position="${position}"] [data-astryx-carousel]`);
            const controls = root.locator('.astryx-carousel-controls');
            const track = root.locator('.astryx-carousel-track');
            await expect(controls).toBeVisible();
            const bounds = await root.evaluate(root => {
              const box = root.getBoundingClientRect();
              const track = root.querySelector('.astryx-carousel-track').getBoundingClientRect();
              const nav = root.querySelector('nav').getBoundingClientRect();
              const children = [...root.querySelector('nav').children].filter(el => el.matches('button, .astryx-carousel-dots')).map(el => el.getBoundingClientRect());
              return {left: box.left, right: box.right, middle: (box.left + box.right) / 2, groupLeft: Math.min(...children.map(r => r.left)), groupRight: Math.max(...children.map(r => r.right)), navTop: nav.top, navBottom: nav.bottom, trackTop: track.top, trackBottom: track.bottom};
            });
            if (position.startsWith('top-')) assert(bounds.navBottom <= bounds.trackTop + 1, `${position}: controls above cards`);
            else assert(bounds.navTop >= bounds.trackBottom - 1, `${position}: controls below cards`);
            const alignment = position.split('-')[1] ?? 'center';
            if (alignment === 'left') assert(Math.abs(bounds.groupLeft - bounds.left) < 2, `${direction}/${position}: left`);
            else if (alignment === 'right') assert(Math.abs(bounds.groupRight - bounds.right) < 2, `${direction}/${position}: right`);
            else assert(Math.abs((bounds.groupLeft + bounds.groupRight) / 2 - bounds.middle) < 2, `${direction}/${position}: center`);
            const dots = controls.locator('[data-carousel-page]:visible');
            await expect(dots).toHaveCount(width === 390 ? 5 : 4);
            const count = await dots.count();
            await page.emulateMedia({reducedMotion: 'reduce'});
            await dots.last().focus();
            await dots.last().press('Enter');
            await expect(dots.last()).toHaveAttribute('aria-current', 'page');
            await expect(controls.locator('[data-next]')).toBeDisabled();
            await expect(controls.locator('[data-position]')).toHaveText(`Page ${count} of ${count}`);
            await expect(dots.last()).toBeFocused();
            const distanceFromEnd = await track.evaluate(track => {
              const box = track.getBoundingClientRect(), last = track.lastElementChild.getBoundingClientRect();
              return getComputedStyle(track).direction === 'rtl' ? last.left - box.left : last.right - box.right;
            });
            assert(Math.abs(distanceFromEnd) <= 2, 'Final dot reaches the end');
            await controls.locator('[data-prev]').click();
            await expect(dots.nth(count - 2)).toHaveAttribute('aria-current', 'page');
            await dots.first().press('Space');
            await expect(dots.first()).toHaveAttribute('aria-current', 'page');
            await expect(controls.locator('[data-prev]')).toBeDisabled();
            // Native track scrolling must also synchronize dot state.
            await track.evaluate(track => { track.scrollLeft = getComputedStyle(track).direction === 'rtl' ? -track.scrollWidth : track.scrollWidth; });
            await expect(dots.last()).toHaveAttribute('aria-current', 'page');
          }
          assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1), 'No mobile page overflow');
          assert.equal(await page.locator('[data-fixture-position="single"] nav:visible').count(), 0);
          assert.equal(await page.locator('[data-fixture-position="disabled"] nav').count(), 0);
          await page.screenshot({path: `${output}/${name}-${mode}-${direction}-${width}.png`, fullPage: true});
        }
      }
      const first = page.locator('[data-fixture-position="top-left"] [data-astryx-carousel]');
      await page.setViewportSize({width: 1100, height: 900});
      // Hide pagination when every card fits, and show it again after resizing.
      await first.evaluate(root => { root.style.width = '2500px'; });
      await expect(first.locator('nav')).toBeHidden();
      await first.evaluate(root => { root.style.width = ''; });
      await expect(first.locator('nav')).toBeVisible();
      for (const theme of ['neutral', 'stone', 'ocean']) for (const colorMode of ['light', 'dark']) {
        await page.locator('body').evaluate((body, values) => { body.dataset.astryxTheme = values.theme; body.dataset.astryxMode = values.colorMode; }, {theme, colorMode});
        const dots = first.locator('[data-carousel-page]:visible');
        await dots.first().click();
        await page.mouse.move(0, 0);
        const styles = await dots.first().evaluate(dot => ({border: getComputedStyle(dot).borderTopWidth, width: dot.getBoundingClientRect().width, height: dot.getBoundingClientRect().height, marker: getComputedStyle(dot.firstElementChild).backgroundColor, markerWidth: dot.firstElementChild.getBoundingClientRect().width}));
        const inactive = await dots.last().locator('span').evaluate(span => getComputedStyle(span).backgroundColor);
        assert.equal(styles.border, '0px'); assert.equal(styles.width, 24); assert.equal(styles.height, 44); assert.equal(styles.markerWidth, 8);
        assert.notEqual(styles.marker, inactive, `${theme}/${colorMode}: active dot visible`);
        const axe = await new AxeBuilder({page}).include('[data-astryx-carousel]').withTags(['wcag2a', 'wcag2aa', 'wcag21aa', 'wcag22aa']).analyze();
        assert.deepEqual(axe.violations.map(v => ({id: v.id, nodes: v.nodes.map(n => n.target)})), [], `${theme}/${colorMode}: accessibility`);
      }
      // Also exercise ordinary smooth scrolling, followed by reduced-motion navigation.
      await page.emulateMedia({reducedMotion: 'no-preference'});
      await first.locator('[data-next]').click();
      await expect(first.locator('[data-carousel-page="1"]')).toHaveAttribute('aria-current', 'page');
      await page.emulateMedia({reducedMotion: 'reduce'});
      await first.locator('[data-prev]').click();
      await expect(first.locator('[data-carousel-page="0"]')).toHaveAttribute('aria-current', 'page');
      assert.deepEqual(errors, []); assert.deepEqual(failedAssets, []);
      await context.close();
      const noJs = await browser.newContext({ignoreHTTPSErrors: true, javaScriptEnabled: false, viewport: {width: 390, height: 844}});
      const fallback = await noJs.newPage();
      await fallback.route(base + '/__astryx-carousel-test__', route => route.fulfill({contentType: 'text/html', body: documentHtml(mode)}));
      await fallback.goto(base + '/__astryx-carousel-test__');
      assert.equal(await fallback.locator('nav:visible').count(), 0);
      assert.equal(await fallback.locator('.astryx-carousel-track > li').count(), 46);
      await expect(fallback.locator('.astryx-carousel-track').first()).toBeVisible();
      assert(await fallback.locator('.astryx-carousel-track').first().evaluate(track => track.scrollWidth > track.clientWidth));
      await noJs.close();
      report.push({browser: name, assets: mode, status: 'passed', positions: 6, directions: 2, widths: [1100, 390]});
      fs.writeFileSync(`${output}/report.json`, JSON.stringify(report, null, 2));
      console.log(`${name}/${mode}: positions, dots, terminal page, resize, keyboard, RTL, themes, reduced motion and no-JS passed`);
    }
  } finally { await browser.close(); }
}
